import { requirePermission } from "@/server/auth/permissions";
import { toErrorResponse } from "@/server/errors";
import { defaultSiteSettings, getSiteSections, getSiteSettings, getSiteSocialLinks, upsertSiteSection, upsertSiteSetting, upsertSiteSocialLink, type SiteSettingKey } from "@/server/site-content";

export const runtime = "nodejs";

export async function GET(request: Request) {
  const requestId = request.headers.get("x-request-id") ?? crypto.randomUUID();

  try {
    await requirePermission("dashboard.read");
    const [settings, sections, socialLinks] = await Promise.all([getSiteSettings(), getSiteSections(), getSiteSocialLinks()]);
    return Response.json({ data: { settings, sections, socialLinks }, requestId });
  } catch (error) {
    return toErrorResponse(error, requestId);
  }
}

export async function PUT(request: Request) {
  const requestId = request.headers.get("x-request-id") ?? crypto.randomUUID();

  try {
    await requirePermission("dashboard.read");
    const payload = await request.json();
    const settings = (payload?.settings ?? {}) as Record<string, string>;
    const sections = (payload?.sections ?? []) as Array<Record<string, unknown>>;
    const socialLinks = (payload?.socialLinks ?? []) as Array<Record<string, unknown>>;

    const { upsertSiteSettingsBulk } = await import("@/server/site-content");
    await upsertSiteSettingsBulk(settings);

    await Promise.all(
      sections.map((section) =>
        upsertSiteSection({
          id: typeof section.id === "string" ? section.id : undefined,
          slug: String(section.slug || ""),
          title: String(section.title || ""),
          description: String(section.description || ""),
          cta_label: String(section.cta_label || ""),
          cta_href: String(section.cta_href || ""),
          enabled: Boolean(section.enabled ?? true),
          sort_order: Number(section.sort_order ?? 0),
          content: (typeof section.content === "object" && section.content !== null ? section.content : {}) as Record<string, unknown>,
        }),
      ),
    );

    await Promise.all(
      socialLinks.map((link) =>
        upsertSiteSocialLink({
          id: typeof link.id === "string" ? link.id : undefined,
          platform: String(link.platform || ""),
          label: String(link.label || ""),
          url: String(link.url || ""),
          enabled: Boolean(link.enabled ?? true),
          sort_order: Number(link.sort_order ?? 0),
        }),
      ),
    );

    return Response.json({ data: { saved: true }, requestId });
  } catch (error) {
    return toErrorResponse(error, requestId);
  }
}

import { getCurrentUser } from "@/server/auth/current-user";
import { toErrorResponse, ApiError } from "@/server/errors";
import { createSupabaseServerClient } from "@/server/supabase/server";
import { updateProfileSchema } from "@/server/validation/profile";

export const runtime = "nodejs";

export async function GET(request: Request) {
  return withRequestId(request, async () => {
    const user = await getCurrentUser();
    const supabase = await createSupabaseServerClient();
    let { data, error } = await supabase.from("profiles").select("*, profile_categories(*), profile_skills(*), social_links(*)").eq("id", user.id).maybeSingle();

    if (error || !data) {
      const { ensureUserProfile } = await import("@/server/auth/current-user");
      await ensureUserProfile(user);
      const retry = await supabase.from("profiles").select("*, profile_categories(*), profile_skills(*), social_links(*)").eq("id", user.id).maybeSingle();
      data = retry.data;
    }

    if (!data) throw new ApiError("NOT_FOUND", "Profile not found.", 404);
    return Response.json({ data });
  });
}

export async function PATCH(request: Request) {
  return withRequestId(request, async () => {
    const user = await getCurrentUser();
    const payload = updateProfileSchema.safeParse(await request.json());

    if (!payload.success) throw new ApiError("VALIDATION_ERROR", "Profile data is invalid.", 400);

    const { ensureUserProfile } = await import("@/server/auth/current-user");
    await ensureUserProfile(user);

    const updates = {
      ...(payload.data.username !== undefined && { username: payload.data.username }),
      ...(payload.data.displayName !== undefined && { display_name: payload.data.displayName }),
      ...(payload.data.avatarUrl !== undefined && { avatar_url: payload.data.avatarUrl }),
      ...(payload.data.bio !== undefined && { bio: payload.data.bio }),
      updated_at: new Date().toISOString(),
    };
    const supabase = await createSupabaseServerClient();
    const { data, error } = await supabase.from("profiles").update(updates).eq("id", user.id).select().single();

    if (error) {
      if (error.code === "23505") throw new ApiError("CONFLICT", "That username is already in use.", 409);
      throw error;
    }

    return Response.json({ data });
  });
}

async function withRequestId(request: Request, handler: () => Promise<Response>) {
  const requestId = request.headers.get("x-request-id") ?? crypto.randomUUID();
  try {
    const response = await handler();
    response.headers.set("x-request-id", requestId);
    return response;
  } catch (error) {
    return toErrorResponse(error, requestId);
  }
}

import { requirePermission } from "@/server/auth/permissions";
import { ApiError } from "@/server/errors";
import { isSupabaseConfigured } from "@/server/env";
import { redirect } from "next/navigation";

export const dynamic = "force-dynamic";

export default async function ControlRoomLayout({ children }: { children: React.ReactNode }) {
  if (!isSupabaseConfigured() && process.env.NODE_ENV !== "production") return children;

  try {
    await requirePermission("dashboard.read");
    return children;
  } catch (error) {
    if (error instanceof ApiError) {
      if (error.code === "UNAUTHENTICATED") {
        redirect("/login?next=/control-room");
      }
      if (error.code === "FORBIDDEN") {
        return (
          <main className="page-wrap">
            <div className="panel" style={{ maxWidth: 600, margin: "40px auto", textAlign: "center" }}>
              <div className="eyebrow" style={{ color: "var(--coral)" }}>Access Restricted</div>
              <h1 style={{ fontSize: 28, margin: "14px 0" }}>Administrator Access Required</h1>
              <p className="member-bio" style={{ margin: "0 0 24px" }}>
                This area is reserved for platform administrators. If you believe this is an error, contact a super admin or sign in with your administrative account.
              </p>
              <div style={{ display: "flex", gap: 12, justifyContent: "center" }}>
                <a href="/" className="button button-ghost">Return to website</a>
                <a href="/login?next=/control-room" className="button button-primary">Switch account</a>
              </div>
            </div>
          </main>
        );
      }
    }
    redirect("/?admin=unavailable");
  }
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { ArrowRight, Bell, Plus, Compass } from "lucide-react";
import { getOptionalUser, ensureUserProfile } from "@/server/auth/current-user";
import { createSupabaseServerClient } from "@/server/supabase/server";
import { getProjects } from "@/lib/supabase-data";
import { ProjectCard } from "@/components/cards";
import { SectionHeading } from "@/components/app-shell";

export const dynamic = "force-dynamic";

export default async function DashboardPage() {
  const user = await getOptionalUser();
  if (!user) {
    redirect("/login?next=/dashboard");
  }

  await ensureUserProfile(user);
  const supabase = await createSupabaseServerClient();

  try {
    const [{ data: profile }, { data: notifications }, projects] = await Promise.all([
      supabase.from("profiles").select("display_name, bio").eq("id", user.id).maybeSingle(),
      supabase.from("notifications").select("id, title, body, created_at").eq("profile_id", user.id).order("created_at", { ascending: false }).limit(5),
      getProjects(user.id),
    ]);

    return (
      <>
        <div className="page-title">
          <div className="eyebrow">Your dashboard</div>
          <h1>
            {profile?.display_name || "Your space"}<br />
            <span style={{ color: "var(--lime)" }}>keep moving.</span>
          </h1>
          <p>{profile?.bio || "Complete your profile so the right people can find you."}</p>
        </div>

        <div className="panel">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
            <h3 style={{ margin: 0 }}>
              <Bell size={15} style={{ verticalAlign: "middle", color: "var(--lime)", marginRight: 8 }} />
              Notifications
            </h3>
            <Link href="/profile" className="section-link">Profile settings <ArrowRight size={12} /></Link>
          </div>
          {notifications?.length ? (
            <div className="activity-list">
              {notifications.map((notification) => (
                <div className="activity" key={notification.id}>
                  <div className="activity-icon">!</div>
                  <div>
                    {notification.title}
                    <span>{notification.body}</span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p className="member-bio">No notifications yet. You will be alerted when other members interact with your projects.</p>
          )}
        </div>

        <section className="section">
          <SectionHeading
            eyebrow="In motion"
            title="Your projects"
            action={<Link href="/projects" className="section-link">View all <ArrowRight size={13} /></Link>}
          />
          <div className="project-grid">
            {projects.map((project) => (
              <ProjectCard key={project.id} project={project} />
            ))}
            <Link
              href="/projects"
              className="project-card"
              style={{ justifyContent: "center", alignItems: "center", color: "var(--muted)", minHeight: 220 }}
            >
              <Plus size={24} color="var(--lime)" />
              <span style={{ marginTop: 10, fontSize: 12, fontWeight: 700, color: "#fff" }}>Submit a new project</span>
            </Link>
          </div>
        </section>

        <section className="section">
          <div className="discord-banner">
            <div>
              <div className="eyebrow">Explore opportunities</div>
              <h2>Find active teams and mentors</h2>
              <p>Browse through ongoing community discussions and open contributor roles.</p>
            </div>
            <div style={{ display: "flex", gap: 10 }}>
              <Link href="/explore" className="button button-ghost">
                <Compass size={14} /> Explore Directory
              </Link>
              <Link href="https://discord.gg/3xfu5TMgF" target="_blank" rel="noreferrer" className="button button-primary">
                Join Discord
              </Link>
            </div>
          </div>
        </section>
      </>
    );
  } catch {
    return (
      <section className="panel">
        <h2>Unable to load your dashboard</h2>
        <p className="member-bio">Please try refreshing the page or sign in again.</p>
        <Link href="/login?next=/dashboard" className="button button-primary" style={{ marginTop: 16 }}>
          Sign in
        </Link>
      </section>
    );
  }
}

